import itertools

def solve():
    # The grid is 4x4. We can represent the placements as a bitmask of 16 bits.
    # No two coins are orthogonally adjacent.
    # Each 2x2 square has at least one coin.

    # Precompute 2x2 square indices
    # A 4x4 grid has (4-1)*(4-1) = 9 such squares.
    squares = []
    for r in range(3):
        for c in range(3):
            # Indices for (r,c), (r,c+1), (r+1,c), (r+1,c+1)
            squares.append([
                r * 4 + c,
                r * 4 + (c + 1),
                (r + 1) * 4 + c,
                (r + 1) * 4 + (c + 1)
            ])

    count = 0
    # Iterate through all possible coin placements (2^16 = 65536)
    for i in range(1 << 16):
        # Check if no two coins are orthogonally adjacent
        possible = True
        # Check rows
        for r in range(4):
            for c in range(3):
                if (i & (1 << (r * 4 + c))) and (i & (1 << (r * 4 + c + 1))):
                    possible = False
                    break
            if not possible: break
        if not possible: continue

        # Check columns
        for c in range(4):
            for r in range(3):
                if (i & (1 << (r * 4 + c))) and (i & (1 << ((r + 1) * 4 + c))):
                    possible = False
                    break
            if not possible: break
        if not possible: continue

        # Check if each 2x2 square has at least one coin
        for sq in squares:
            has_coin = False
            for idx in sq:
                if i & (1 << idx):
                    has_coin = True
                    break
            if not has_coin:
                possible = False
                break

        if possible:
            count += 1

    return count

if __name__ == "__main__":
    result = solve()
    print(f"ANSWER: {result}")

